 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 void install(){remove();final boolean left=GestureSettings.number(prefs,"side",0,0,1)==0;int position=GestureSettings.number(prefs,"position",1,0,2),width=GestureSettings.number(prefs,"width",16,8,32),height=GestureSettings.number(prefs,"height",160,80,320);Point screen=new Point();windows.getDefaultDisplay().getSize(screen);WindowManager.LayoutParams params=new WindowManager.LayoutParams(dp(width),Math.max(dp(32),Math.min(dp(height),Math.max(dp(32),screen.y-dp(48)))),Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);params.gravity=(left?Gravity.LEFT:Gravity.RIGHT)|(position==0?Gravity.TOP:position==2?Gravity.BOTTOM:Gravity.CENTER_VERTICAL);params.x=0;params.y=position==1?0:dp(24);params.setTitle("legacydash invisible edge gesture trigger");View trigger=new View(this);trigger.setBackgroundColor(testing?0x665a9dea:Color.TRANSPARENT);trigger.setContentDescription("User-enabled legacydash edge gesture area");trigger.setOnTouchListener(new View.OnTouchListener(){float x,y;long began=0,lastTap=0;float tapX,tapY;boolean down=false;public boolean onTouch(View view,MotionEvent event){int action=event.getActionMasked();if(event.getPointerCount()>1||action==MotionEvent.ACTION_CANCEL){down=false;lastTap=0;return true;}if(action==MotionEvent.ACTION_DOWN){x=event.getRawX();y=event.getRawY();began=event.getEventTime();down=true;return true;}if(action!=MotionEvent.ACTION_UP||!down)return true;down=false;float dx=event.getRawX()-x,dy=event.getRawY()-y,inward=left?dx:-dx;long elapsed=event.getEventTime()-began;int travel=dp(GestureSettings.number(prefs,"travel",64,32,160));if(elapsed<=1200&&inward>=travel&&Math.abs(dy)<=Math.max(dp(48),travel*1.5f)){lastTap=0;fire("swipe","Inward swipe");return true;}if(Math.hypot(dx,dy)>dp(24)){lastTap=0;return true;}if(elapsed>=650){lastTap=0;fire("hold","Hold and release");return true;}long now=event.getEventTime();if(lastTap>0&&now-lastTap<=ViewConfiguration.getDoubleTapTimeout()&&Math.hypot(x-tapX,y-tapY)<=dp(48)){lastTap=0;fire("double","Double tap");}else{lastTap=now;tapX=x;tapY=y;}return true;}});windows.addView(trigger,params);edge=trigger;}
 void fire(String gesture,String label){long now=SystemClock.elapsedRealtime();if(now-lastAction<750)return;String action=prefs.getString(GestureSettings.P+gesture,gesture.equals("swipe")?"legacydash":"none");if(testing){lastAction=now;Toast.makeText(this,label+" / "+GestureSettings.actionLabel(this,action),Toast.LENGTH_SHORT).show();return;}if(action.equals("none"))return;try{Intent intent;if(action.equals("legacydash"))intent=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(getPackageName(),"local.skyfamily.CalendarPhotosActivity");else{ComponentName component=ComponentName.unflattenFromString(action);if(component==null)throw new ActivityNotFoundException();ActivityInfo info=getPackageManager().getActivityInfo(component,0);if(!info.enabled||!info.exported||!info.applicationInfo.enabled)throw new ActivityNotFoundException();intent=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(component);}lastAction=now;intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT);startActivity(intent);}catch(Exception failure){Toast.makeText(this,"Gesture app launch unavailable / change its action in Settings",Toast.LENGTH_LONG).show();}}
